INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62711257', 62711257, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'POLITEKNIK PERKERETAAPIAN INDONESIA MADIUN', 'Pengadaan Jasa Tenaga Kebersihan', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Madiun (Kota)', 1187100000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Jasa Tenaga Kebersihan merupakan kegiatan penyediaan 27 orang tenaga kebersihan untuk mendukung kebersihan, kerapian, dan kenyamanan lingkungan kerja di kawasan Politeknik Perkeretaapian Indonesia Madiun. Layanan ini dilaksanakan untuk menunjang operasional dan pemeliharaan kantor, dengan penugasan tenaga kebersihan yang memiliki kualifikasi sesuai kebutuhan serta menjamin standar kebersihan, kesehatan, dan kenyamanan lingkungan kerja secara berkelanjutan.', 'Spesifikasi Teknis pengadaan jasa tenaga kebersihan meliputi penyediaan 27 orang tenaga kebersihan dengan kualifikasi minimal pendidikan SMP/sederajat, usia 21–50 tahun, dan pengalaman kerja 1–3 tahun. Tenaga kebersihan dilengkapi seragam dan atribut kerja, bertugas menjaga kebersihan area kantor dan lingkungan kampus sesuai jadwal kerja yang ditetapkan. Penyedia wajib menjamin kehadiran minimal 95%, menyediakan tenaga pengganti maksimal 1 hari apabila terjadi ketidakhadiran, serta menanggung seluruh komponen biaya termasuk gaji, BPJS Kesehatan, BPJS Ketenagakerjaan, THR, manajemen fee, dan seragam, dengan pengawasan oleh koordinator lapangan dan pelaporan kinerja secara berkala.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 760384);
