INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63213941', 63213941, 'analyze_legacy', 'Kota Bontang', 'kabkota', 'Dinas Pemuda, Olah Raga, dan Pariwisata', 'Belanja Pakaian Dinas Lapangan (PDL) (Pendidikan Latihan Dasar KOKAM Muhammadiyah)', 'Barang', 'E-Purchasing', 'Kalimantan Timur, Bontang (Kota)', 63000000, 'April 2026', 'APBD', 1, 1, '1 Paket', 'Pakaian Dinas Lapangan (PDL) Tipe 2;', 'PDL dan Atributnya;', 63000000, 'high', 'Pengadaan pakaian dinas lapangan dan atribut untuk kegiatan organisasi kemasyarakatan/keagamaan non-aparatur terindikasi kurang selaras dengan fungsi belanja barang pemerintah daerah. Dari judul dan spesifikasi, manfaatnya lebih menyerupai dukungan perlengkapan pihak eksternal daripada kebutuhan operasional kedinasan, sehingga seluruh nilai patut dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 763721);
