INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62689327', 62689327, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA TRENGGALEK', 'Belanja Keperluan Perkantoran berupa Pengadaan Outsourcing', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Terenggalek (Kab.)', 338676000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '6 Org', 'Pengadaan Outsourcing Tenaga Keamanan dan Tenaga Kebersihan', '1. Lingkup Pekerjaan (Scope of Work) A. Tenaga Pengamanan (Security) Pengamanan Fisik: Menjaga aset, gedung, dan area parkir dari pencurian, pengerusakan, atau akses tidak sah. Pengaturan Lalu Lintas: Mengatur keluar masuk kendaraan dan tamu sesuai SOP. Patroli Rutin: Melakukan kontrol area secara berkala (minimal 1-2 jam sekali). Tanggap Darurat: Melakukan tindakan awal jika terjadi kebakaran, kerusuhan, atau bencana alam. Pelaporan: Menyusun jurnal harian, laporan insiden, dan koordinasi dengan aparat kepolisian setempat jika diperlukan. B. Tenaga Kebersihan (Cleaning Service) Area Dalam (Indoor): Pembersihan lantai (sweeping & mopping), kaca, meja, kursi, toilet, dan pembuangan sampah harian. Area Luar (Outdoor): Pembersihan halaman, selokan, dan area parkir. Deep Cleaning: Pembersihan berkala (mingguan/bulanan) seperti kristalisasi marmer atau pencucian karpet. General Cleaning: Pembersihan total pada area tertentu sesuai permintaan khusus. C. Kualifikasi Personil: Kriteria Tenaga Keamanan Pendidikan Min. SMA/Sederajat Sertifikasi Wajib memiliki Sertifikat Gada Pratama Usia 20 – 40 Tahun Kesehatan Sehat jasmani & rohani, tidak bertato/tindik Dokumen SKCK aktif, bebas Narkoba Kriteria Tenaga Kebersihan Pendidikan Min. SMP/SMA Sertifikasi minimal memiliki Pelatihan Basic Cleaning (Opsional) Usia 18 – 40 Tahun Kesehatan Sehat jasmani & rohani, tidak bertato/tindik Dokumen SKCK aktif 2. Manajemen & Pengawasan (SLA) Penyedia jasa wajib memenuhi Service Level Agreement (SLA) sebagai berikut: Response Time: Petugas keamanan harus sigap merespons keluhan atau ancaman dalam waktu kurang dari 5 menit. Standar Kebersihan: Area toilet tidak boleh berbau dan lantai tidak boleh licin/berdebu (evaluasi dilakukan melalui checklist harian). Penggantian Personel (Replacement): Jika ada personel berhalangan (sakit/izin), penyedia wajib menyediakan pengganti (back-up) dalam waktu maksimal 2 jam. Kedisiplinan: Tingkat kehadiran personel minimal 98% setiap bulan. 3. Kewajiban Pemenuhan Hak Karyawan Penyedia jasa wajib mematuhi regulasi ketenagakerjaan yang berlaku: Pembayaran gaji minimal sesuai UMK/UMP setempat. Pendaftaran dan pembayaran iuran BPJS Ketenagakerjaan dan BPJS Kesehatan. Pemberian Tunjangan Hari Raya (THR). Penyediaan Alat Pelindung Diri (APD) yang layak. 4. Dokumen Administrasi yang Dibutuhkan Surat Izin Operasional Badan Usaha Jasa Pengamanan (BUJP) dari Mabes Polri (untuk Keamanan). Surat Izin Operasional Perusahaan Penyedia Jasa Pekerja/Buruh (PPJP). Bukti setor pajak tahun terakhir.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 763767);
