INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62688612', 62688612, 'analyze_legacy', 'Universitas Diponegoro', 'central', 'Universitas Diponegoro', 'Pengadaan Jasa Outsourcing Tenaga Administrasi, Tenaga Teknisi, dan Tenaga Pengemudi Fakultas Ilmu Sosial dan Ilmu Politik Universitas Diponegoro Tahun 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 1549419912, 'January 2026', 'Lainnya', 0, 1, '1', 'Jenis jasa lainnya yang akan diadakan dalam paket pengadaan ini adalah jasa outsourcing tenaga pendukung operasional, yang meliputi penyediaan Tenaga Administrasi, Tenaga Teknisi, dan Tenaga Pengemudi oleh penyedia jasa yang memiliki izin usaha dan kompetensi. Tenaga Administrasi yang dimaksud mencakup Tenaga Administrasi IT Support, Desain Komunikasi Visual dan Web, serta Administrasi WCU dan IUP Fakultas Ilmu Sosial dan Ilmu Politik Universitas Diponegoro, yang bertugas mendukung kelancaran layanan administrasi, pengelolaan sistem teknologi informasi, pengelolaan konten komunikasi, serta layanan pendukung internasionalisasi fakultas. Selain itu, pengadaan ini juga mencakup Tenaga Teknisi (Sarana dan Prasarana) yang berfungsi untuk mendukung pemeliharaan, perawatan, dan penanganan teknis terhadap fasilitas dan infrastruktur Fakultas Ilmu Sosial dan Ilmu Politik Universitas Diponegoro agar tetap berfungsi dengan baik. Selanjutnya, Tenaga Pengemudi disediakan untuk mendukung mobilitas dan kelancaran kegiatan operasional, kedinasan, serta kegiatan institusional fakultas. Seluruh tenaga outsourcing tersebut berada di bawah pengelolaan dan tanggung jawab penyedia', '1. pendidikan minimal tenaga terampil a. Tenaga Administrasi - Berpenampilan Menarik - Menguasai Bahasa Inggris aktif - Ramah, sopan, rajin, bersih dan inisiatif - Memiliki dasar MS Office - minimal S1 - Usia maksimal 30 tahun b. Tenaga IT Support - Minimum Diploma di bidang IT - pengalaman kerja selama 1 tahun. - Mampu dan mau melakukan tugas administrasi umum. - pemahaman dan keterampilan dalam hal instalasi komputer. - Mempunyai pemahaman pengoperasian perangkat pendukung seperti printer, scanner, dll; dan - Menguasai perkembangan teknologi c. Tenaga Teknisi Sarpras - SMA/SMK bidang Mesin/Listrik atau bidang lain relevan tugas jabatan. - Berpenampilan menarik - Ramah, sopan, rajin dan inisiatif - Mampu bekerja dalam tekanan - Sehat jasmani, rohani, dan tidak buta warna. - Tidak mengonsumsi obat terlarang d. Tenaga Pengemudi - Berpenampilan Menarik. - Ramah, sopan, rajin, bersih dan inisiatif. - Memiliki SIM A. - minimal SMA - Berpengalaman pengemudi minimal 1 tahun', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 763775);
