INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62714069', 62714069, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'POLITEKNIK PERKERETAAPIAN INDONESIA MADIUN', 'Pengadaan Jasa Tenaga Keamanan', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Madiun (Kota)', 776064000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Jasa Tenaga Keamanan merupakan kegiatan penyediaan tenaga pengamanan profesional untuk menjaga keamanan, ketertiban, dan keselamatan lingkungan kampus Politeknik Perkeretaapian Indonesia Madiun. Layanan ini mencakup penugasan personel keamanan yang memiliki kualifikasi, pengalaman kerja, serta sertifikat kompetensi yang sesuai, dilengkapi seragam dan atribut pengamanan, serta dilaksanakan secara bergilir sesuai sistem shift. Pengadaan ini bertujuan untuk mendukung operasional dan pemeliharaan kantor, pengamanan aset, pengendalian akses, patroli rutin, dan penanganan kondisi darurat secara berkelanjutan.', 'Spesifikasi Teknis pengadaan jasa tenaga keamanan meliputi penyediaan personel pengamanan yang memiliki pendidikan minimal SLTA/sederajat, pengalaman kerja 1–3 tahun, dan sertifikat kompetensi Gada Pratama, dengan rentang usia 21–50 tahun. Personel dilengkapi seragam dan atribut pengamanan, bertugas melaksanakan pengamanan kawasan kampus melalui sistem shift, meliputi pengaturan akses, patroli rutin, pengawasan aset, serta penanganan kondisi darurat. Penyedia wajib menjamin tingkat kehadiran minimal 95%, menyediakan tenaga pengganti maksimal 2 jam apabila terjadi ketidakhadiran, menyediakan koordinator/supervisor, serta menanggung seluruh komponen biaya