INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62688466', 62688466, 'analyze_legacy', 'Universitas Diponegoro', 'central', 'Universitas Diponegoro', 'Pengadaan Jasa Outsourcing Tenaga Kebersihan Fakultas Ilmu Sosial Dan Ilmu Politik Universitas Diponegoro Tahun 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 1525639170, 'January 2026', 'Lainnya', 0, 1, '1', 'Macam/jenis jasa lainnya yang akan diadakan adalah jasa outsourcing tenaga kebersihan (cleaning service) yang meliputi pelayanan kebersihan dan pemeliharaan lingkungan di seluruh area Fakultas Ilmu Sosial dan Ilmu Politik Universitas Diponegoro. Jasa ini mencakup kegiatan kebersihan rutin dan berkala pada area dalam gedung maupun area luar gedung, termasuk ruang perkuliahan, ruang perkantoran, ruang rapat, auditorium, laboratorium, perpustakaan, koridor, lobi, toilet, tangga, serta fasilitas umum lainnya. Selain itu, jasa outsourcing tenaga kebersihan juga meliputi pembersihan area luar gedung seperti halaman, taman, area parkir, dan lingkungan sekitar fakultas, guna menjaga kebersihan, kerapian, dan kenyamanan lingkungan kampus. Jasa ini termasuk kegiatan pengangkutan dan pengelolaan sampah sementara sesuai dengan ketentuan yang berlaku, serta pelaksanaan kebersihan khusus atau insidental untuk mendukung kegiatan akademik dan non-akademik, seperti seminar, wisuda, dan kegiatan institusional lainnya', 'Tingkat pendidikan minimal tenaga terampil yang dibutuhkan; 1. Tenaga Koordinator Kebersihan - Minimal berijazah SMA Sederajat. - Berpengalaman profesional Cleaning service / Housekeeping minimal 2 (dua) tahun. - Memiliki sertifikat Pelatihan sosialisasi/orientasi Keselamatan dan Kesehatan kerja dan Housekeeping yang dikeluarkan oleh Instansi Pemerintah ataupun swasta. 2. Tenaga Pelaksana Kebersihan - Pendidikan minimal SMA Sederajat. - Memiliki Pelatihan sosialisasi/orientasi sertifikat Pelatihan Houskeeping dan Keselamatan dan Kesehatan kerja yang di keluarkan oleh Instansi Pemerintah ataupun swasta. - Sehat jasmani dan rohani. - Tidak menggunakan narkoba. - Rajin, ramah, sopan dan tanggap serta berkelakuan baik. 3. Tenaga Pramukantor - Berpenampilan Menarik - Ramah, Sopan, Rajin, bersih dan inisiatif - Pendidikan minimal SMA Sederajat - Berpengalaman sebagai pramukantor minimal 1 tahun', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 764145);
