INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62716845', 62716845, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'Pendidikan dan Pelatihan Anti Pencucian Uang PPATK', 'Pengadaan Jasa Pest Control  Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Depok (Kota)', 78000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1 Paket )', 'Pekerjaan meliputi jasa pengendalian hama (Pest Control) dan pengendalian ular (Snake Control) pada seluruh area Pusdiklat APUPPT, baik area dalam gedung (indoor) maupun area luar gedung (outdoor), termasuk tetapi tidak terbatas pada: a. Ruang perkantoran; b. Ruang kelas dan asrama; c. Gudang dan ruang arsip; d. Dapur, kantin, dan area makanan; e. Saluran air, taman, semak, dan area terbuka; dan f. Area rawan munculnya ular. Jenis Hama yang Dikendalikan: a. Serangga: kecoa, semut, nyamuk, lalat, rayap; b. Rodentia: tikus; dan c. Reptil: ular (penangkapan dan pencegahan masuk area).', 'Pest Control, yang terdiri dari: a. Pest Control: Nyamuk, Lalat, Kecoa, Semut Melakukan pengasapan (thermal fogging), pengembunan (cold fogging), penyemprotan (spraying) dan atau pengumpanan (baiting) pada area-area yang berpotensi menjadi sarang atau sumber hama baik di area indoor maupun outdoor bangunan. b. Rodent Control: Tikus Melakukan pemasangan rodent box yang akan kami beri umpan tikus di dalamnya yang akan di pasang pada area outdoor bangunan dan pemasangan rodent glue trap dan trays bait di area indoor bangunan pada area-area yang berpotensi menjadi sarang atau sumber hama. c. Snake Control: Pengendalian Ular 1) Melakukan inspeksi pada area-area yang berpotensi sebagai tempat ular berkembang biak dan beristirahat, serta penangkapan apabila ditemukan ular pada saat inspeksi; 2) Penempatan perangkap ular (Snake trap), pada titik-titik strategis yang berpotensi sebagai tempat ular melintas. Qty = 12 Bulan (1 bulan terdiri dari 2 kegiatan kunjungan) Tenaga Teknis: Jumlah personel untuk pekerjaan Pest Control dan Snake Control adalah minimal 3 (tiga) personel per kunjungan. Peralatan: Peralatan yang digunakan pada saat pemeliharaan untuk Pest Control yaitu ULV Cold Fogger, Hand Sprayer dan Thermal Fogger, untuk Rodent Control yaitu Rodent Box, Plastic Tray/Trigonal Box dan Trays Bait, untuk Snake Control yaitu Snake Tang dan Snake Trap.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 767540);
